<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVariable\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;

use OpenApi\Attributes as OA;
use Throwable;

use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\LongTask\Runner;
use Civi\Lughauth\Shared\Infrastructure\LongTask\TaskKey;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Enable\TemplateVariableEnableUsecase;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableFilter;
use Civi\Lughauth\Features\Document\TemplateVariable\Infrastructure\Driver\Batch\TemplateVariableTaskEnable;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableUidVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableCodeVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableTypeVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableValueVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableEnabledVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Enable\TemplateVariableEnableResult;

class TemplateVariableEnableController
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly Runner $runner,
    private readonly SqlTemplate $sql,
    private readonly TemplateVariableEnableUsecase $enableUsecase,
  ) {
  }
  #[OA\Patch(path: "/api/document/template-variable/{uid}/enable", tags: ["Template variable"], description: "Update the value",
    parameters: [
      new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
    responses: [
      new OA\Response(response: 200, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TemplateVariableApiDTO")),
      new OA\Response(response: 404, description: "Not found"),
    ])
  ]
  public function enable(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("enable for Template variable");
    $span = $this->startSpan("enable for Template variable");
    $this->sql->begin();
    try {
      if (!isset($args['uid'])) {
        throw new NotFoundException('-');
      }
      $uid = $args['uid'];
      $result = $this->enableUsecase->enable($uid);
      $this->sql->commit();
      $value = $this->mapTemplateVariable($request, $result);
      $encoded = json_encode($value);
      $response->getBody()->write( $encoded === false ? '' : $encoded );
      return $response->withStatus(201)
            ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $this->sql->close();
      $span->end();
    }
  }
  public function enableAllForQuery(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("enable all for query Template variable");
    $span = $this->startSpan("enable all for query Template variable");
    try {
      $params = $request->getQueryParams();
      $filter = new TemplateVariableFilter(
        uids: isset( $params['uid'] ) ? [$params['uid']] : ( isset($params['uids']) ? explode(',', $params['uids']) : null),
        search: $params['search'] ?? null,
        code: $params['code'] ?? null,
        tenant: isset($params['tenant'])? new TenantRef($params['tenant']): null,
        tenants: isset($params['tenants'])? explode(",", $params['tenants']): null,
      );
      $res = $this->runner->run(TemplateVariableTaskEnable::class, ['filter' => $filter]);
      $encoded = json_encode($res);
      $response->getBody()->write( $encoded === false ? '' : $encoded );
      return $response;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function checkEnableAllForQueryStatus(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("Check enable all for query Template variable");
    $span = $this->startSpan("Check enable all for query Template variable");
    try {
      if (!isset($args['uid'])) {
        throw new NotFoundException('-');
      }
      $uid = $args['uid'];
      $info = $this->runner->detail( new TaskKey($uid) );
      if( !$info ) {
        throw new NotFoundException('-');
      }
      $encoded = json_encode($info);
      $response->getBody()->write( $encoded === false ? '' : $encoded );
      return $response->withStatus(200)
        ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }

  private function mapTemplateVariable(ServerRequestInterface $request, TemplateVariableEnableResult $value): TemplateVariableApiDTO
  {
    $this->logDebug("Map entity to output dto for Template variable");
    $span = $this->startSpan("Map entity to output dto for Template variable");
    try {
      $tenant = $value->getTenant();
      $dto = new TemplateVariableApiDTO();
      $dto->uid = $value->getUid();
      $dto->code = $value->getCode();
      $dto->tenant = $tenant ? ['$ref' => $tenant->uid()] : null;
      $dto->type = $value->getType();
      $dto->value = $value->getValue();
      $dto->enabled = $value->isEnabled();
      $dto->version = $value->getVersion();
      return $dto;
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
